--- index.html
+++ index.html
@@ -30,6 +30,32 @@
 <div class="mobile"><div class="stick" id="stick"><i class="knob" id="knob"></i></div><div class="mobbuttons"><button class="mobbtn ult" id="mUlt">ULT</button><button class="mobbtn" id="mPulse">PULSE</button><button class="mobbtn big" id="mFire">FIRE</button><button class="mobbtn" id="mDash">DASH</button></div></div><div class="mobile-tip">DRAG TO MOVE · TAP FIRE / ABILITIES</div>
 <div class="toast" id="toast">FIGHT!</div>
 <div class="intro" id="intro"><div class="card"><div class="overline">ONE ARENA. ONE SURVIVOR.</div><h1>RIFT<span>DUEL</span></h1><div class="subtitle">A 3D-inspired top-down hero arena. Outmaneuver the Warden,<br>land your shots, and control the center.</div><div class="versus"><div><div class="portrait">✦</div><label>NYX · RUNNER</label></div><strong>VS</strong><div><div class="portrait foe">◈</div><label>VEX · WARDEN</label></div></div><button class="start" id="start">ENTER THE ARENA</button><div class="footnote">WASD MOVE · MOUSE AIM · CLICK FIRE · Q DASH · E PULSE · F ULT</div></div></div>
 <script>
-</script>
+(()=>{
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
+const $=s=>document.querySelector(s), clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
+let W=0,H=0,S=1,cy=0,active=false,ended=false,muted=false,last=0,elapsed=0,roundTime=90,shake=0,mouse={x:0,y:0,down:false},keys={},mobileAim=0;
+const bounds={x:10.8,y:6.7};
+const player={x:-5.5,y:0,vx:0,vy:0,r:.58,hp:100,max:100,ult:0,angle:0,fire:0,dash:0,dashCd:0,pulseCd:0,inv:0,flash:0,over:0,side:1};
+const enemy={x:5.5,y:0,vx:0,vy:0,r:.62,hp:100,max:100,ult:0,angle:Math.PI,fire:1,dash:0,dashCd:2,pulseCd:3,inv:0,flash:0,side:-1};
+let bullets=[],particles=[],rings=[],stars=Array.from({length:90},()=>({x:Math.random(),y:Math.random(),a:rand(.15,.55),r:rand(.4,1.4)}));
+const blocks=[{x:-1.6,y:-3.35,w:1.55,h:.62},{x:1.6,y:-3.35,w:1.55,h:.62},{x:-1.6,y:3.35,w:1.55,h:.62},{x:1.6,y:3.35,w:1.55,h:.62},{x:-7.1,y:-2.7,w:.78,h:1.2},{x:7.1,y:2.7,w:.78,h:1.2},{x:7.1,y:-2.7,w:.78,h:1.2},{x:-7.1,y:2.7,w:.78,h:1.2}];
+function resize(){let d=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*d;canvas.height=H*d;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(d,0,0,d,0,0);S=Math.min(W/25.5,H/17.2);cy=H*.535;mouse.x=W/2;mouse.y=cy}
+addEventListener('resize',resize);resize();
+function toScreen(x,y){return{x:W/2+x*S,y:cy+y*S*.78}}
+function toWorld(x,y){return{x:(x-W/2)/S,y:(y-cy)/(S*.78)}}
+function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
+function reset(){Object.assign(player,{x:-5.5,y:0,vx:0,vy:0,hp:100,ult:0,fire:0,dash:0,dashCd:0,pulseCd:0,inv:0,flash:0,over:0});Object.assign(enemy,{x:5.5,y:0,vx:0,vy:0,hp:100,ult:0,fire:.7,dash:0,dashCd:2,pulseCd:3,inv:0,flash:0});bullets=[];particles=[];rings=[];elapsed=0;roundTime=90;ended=false;active=true;$('#intro').classList.add('hidden');say('FIGHT!');updateHud()}
+$('#start').onclick=reset;$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent='SOUND: '+(muted?'OFF':'ON')};
+function say(text){let t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>t.classList.remove('show'),900)}
+function endGame(win){if(ended)return;ended=true;active=false;$('#intro').classList.remove('hidden');$('.card').classList.add('endcard');$('.overline').textContent=win?'ARENA SECURED':'SIGNAL LOST';$('.card h1').innerHTML=win?'VICTORY<span>★</span>':'DEFEAT<span>×</span>';$('.subtitle').innerHTML=win?'Vex is down. The arena belongs to you.':'The Warden won this round. Reset and take the center.';$('.versus').style.display='none';$('#start').textContent='REMATCH';$('.footnote').textContent='YOUR ARENA RECORD · '+(win?'1 WIN':'0 WINS')+' / '+(win?'0 LOSSES':'1 LOSS')}
+function startScreen(){ended=false;active=false;$('.card').classList.remove('endcard');$('.overline').textContent='ONE ARENA. ONE SURVIVOR.';$('.card h1').innerHTML='RIFT<span>DUEL</span>';$('.subtitle').innerHTML='A 3D-inspired top-down hero arena. Outmaneuver the Warden,<br>land your shots, and control the center.';$('.versus').style.display='flex';$('#start').textContent='ENTER THE ARENA';$('.footnote').textContent='WASD MOVE · MOUSE AIM · CLICK FIRE · Q DASH · E PULSE · F ULT'}
+function updateHud(){for(const [p,n] of [[player,1],[enemy,2]]){$('#hp'+n).style.width=(p.hp/p.max*100)+'%';$('#hptext'+n).textContent=Math.ceil(p.hp)+' / 100';$('#ulttext'+n).innerHTML=(n===1?'◈ PHASE CHARGE ':'◈ CORE CHARGE ')+'<span>'+Math.floor(p.ult)+'%</span>'}$('#ultbar').style.width=player.ult+'%';$('#abDash').classList.toggle('cool',player.dashCd>0);$('#abDash').classList.toggle('ready',player.dashCd<=0);$('#abPulse').classList.toggle('cool',player.pulseCd>0);$('#abPulse').classList.toggle('ready',player.pulseCd<=0);$('#abUlt').classList.toggle('ready',player.ult>=100);$('#abUlt').classList.toggle('cool',player.ult<100);let t=Math.ceil(roundTime);$('#timer').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');$('#timer').classList.toggle('low',t<=15);let a=toScreen(player.x,player.y),b=toScreen(enemy.x,enemy.y);$('#dot1').style.left=clamp((a.x/W)*100,8,92)+'%';$('#dot1').style.top=clamp(((a.y-(cy-S*6.7*.78))/(S*13.4*.78))*100,12,88)+'%';$('#dot2').style.left=clamp((b.x/W)*100,8,92)+'%';$('#dot2').style.top=clamp(((b.y-(cy-S*6.7*.78))/(S*13.4*.78))*100,12,88)+'%'}
+function addParticle(x,y,color,n=8,power=2){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(.4,power);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.65),max:.65,color,size:rand(.035,.1)})}}
+function shoot(p,target,team,spread=0){let a=p.angle+rand(-spread,spread),speed=team==='player'?17:13;let ox=p.x+Math.cos(a)*.72,oy=p.y+Math.sin(a)*.72;bullets.push({x:ox,y:oy,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:1.35,team,damage:team==='player'?10:7,color:team==='player'?'#65fff0':'#ff668d',r:team==='player'?.12:.14});addParticle(ox,oy,team==='player'?'#75fff2':'#ff7793',3,1.1)}
+function dash(p,dx,dy){if(p.dashCd>0)return;let m=Math.hypot(dx,dy);if(m<.01){dx=Math.cos(p.angle);dy=Math.sin(p.angle)}else{dx/=m;dy/=m}p.vx=dx*17;p.vy=dy*17;p.dash=.18;p.dashCd=2.8;p.inv=.38;addParticle(p.x,p.y,p===player?'#6affef':'#ff648a',16,2.4)}
+function pulse(p,who){if(p.pulseCd>0)return;p.pulseCd=5.5;rings.push({x:p.x,y:p.y,r:.4,max:4.2,life:.45,color:p===player?'#64fff0':'#ff648a'});addParticle(p.x,p.y,p===player?'#64fff0':'#ff648a',22,3);let dx=who.x-p.x,dy=who.y-p.y,d=Math.hypot(dx,dy);if(d<4.2){who.hp=Math.max(0,who.hp-16);who.vx+=dx/(d||1)*8;who.vy+=dy/(d||1)*8;who.flash=.16;p.ult=Math.min(100,p.ult+16);shake=.18}}
+function ultimate(p,who){if(p.ult<100)return;p.ult=0;p.over=3.3;p.inv=.4;let c=p===player?'#a1fff7':'#ff8aaa';rings.push({x:p.x,y:p.y,r:.5,max:5.8,life:.65,color:c});addParticle(p.x,p.y,c,45,5);if(Math.hypot(p.x-who.x,p.y-who.y)<5.8){who.hp=Math.max(0,who.hp-22);who.vx+=(who.x-p.x)*2;who.vy+=(who.y-p.y)*2;who.flash=.25}say('OVERDRIVE');shake=.35}
+function hit(p,b){if(p.inv>0)return;p.hp=Math.max(0,p.hp-b.damage);p.flash=.16;addParticle(p.x,p.y,b.color,8,1.8);shake=.12;if(b.team==='player')player.ult=Math.min(100,player.ult+11);else enemy.ult=Math.min(100,enemy.ult+9)}
+
 </body></html>
\ No newline at end of file

