function hit(p,b){if(p.inv>0)return;p.hp=Math.max(0,p.hp-b.damage);p.flash=.16;addParticle(p.x,p.y,b.color,8,1.8);shake=.12;if(b.team==='player')player.ult=Math.min(100,player.ult+11);else enemy.ult=Math.min(100,enemy.ult+9)}
function drawArena(){let g=ctx.createRadialGradient(W*.5,H*.48,20,W*.5,H*.5,Math.max(W,H)*.8);g.addColorStop(0,'#192130');g.addColorStop(.52,'#0c111c');g.addColorStop(1,'#070a12');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);for(let s of stars){ctx.fillStyle=`rgba(133,180,210,${s.a})`;ctx.fillRect(s.x*W,s.y*H,s.r,s.r)}ctx.save();ctx.translate(W/2,cy);ctx.scale(S,S*.78);
// cast shadow and beveled arena body
ctx.fillStyle='#02040a';roundRect(ctx,-12.1,-7.95,24.2,15.9,.75);ctx.fill();ctx.fillStyle='#111a27';roundRect(ctx,-12,-8.25,24,16.5,.75);ctx.fill();ctx.strokeStyle='#344052';ctx.lineWidth=.09;ctx.stroke();
let floor=ctx.createLinearGradient(0,-8,0,8);floor.addColorStop(0,'#172232');floor.addColorStop(.5,'#111a28');floor.addColorStop(1,'#121b2a');ctx.fillStyle=floor;roundRect(ctx,-11.7,-7.95,23.4,15.9,.55);ctx.fill();
ctx.save();roundRect(ctx,-11.7,-7.95,23.4,15.9,.55);ctx.clip();ctx.strokeStyle='rgba(104,145,171,.075)';ctx.lineWidth=.025;for(let x=-11;x<=11;x+=1){ctx.beginPath();ctx.moveTo(x,-8);ctx.lineTo(x,8);ctx.stroke()}for(let y=-7;y<=7;y+=1){ctx.beginPath();ctx.moveTo(-12,y);ctx.lineTo(12,y);ctx.stroke()}
// cyan and magenta lane lighting
let gl=ctx.createLinearGradient(-11,0,11,0);gl.addColorStop(0,'#55e4d500');gl.addColorStop(.5,'#55e4d514');gl.addColorStop(1,'#fa547e00');ctx.fillStyle=gl;ctx.fillRect(-11,-7.9,22,15.8);
// center ring and inner target
ctx.strokeStyle='#57e5dd33';ctx.lineWidth=.07;ctx.beginPath();ctx.arc(0,0,3.8,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#57e5dd4c';ctx.lineWidth=.035;ctx.beginPath();ctx.arc(0,0,2.7,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#5be6e60d';ctx.beginPath();ctx.arc(0,0,2.65,0,Math.PI*2);ctx.fill();for(let i=0;i<4;i++){let a=i*Math.PI/2;ctx.save();ctx.translate(Math.cos(a)*3.3,Math.sin(a)*3.3);ctx.rotate(a);ctx.fillStyle='#5be6e641';ctx.fillRect(-.12,-.04,.24,.08);ctx.restore()}
// panels
for(let x=-10;x<=10;x+=2){ctx.fillStyle=x<0?'#62e3dc0e':'#ff547e0b';ctx.fillRect(x,-7.75,1.8,.08);ctx.fillRect(x,7.67,1.8,.08)}
ctx.restore();
// corner pylons
for(let x of [-10.65,10.65])for(let y of [-6.9,6.9]){ctx.fillStyle='#050910';roundRect(ctx,x-.42,y-.42,.84,.84,.13);ctx.fill();ctx.fillStyle='#222d3a';roundRect(ctx,x-.4,y-.48,.8,.8,.12);ctx.fill();ctx.fillStyle=x<0?'#54eee3':'#ff5b83';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=.32;ctx.fillRect(x-.17,y-.45,.34,.06);ctx.shadowBlur=0;ctx.strokeStyle='#5a697b';ctx.lineWidth=.04;ctx.strokeRect(x-.29,y-.34,.58,.58)}
for(const o of blocks){ctx.fillStyle='#070b12';roundRect(ctx,o.x-o.w/2,o.y-o.h/2+.18,o.w,o.h,.15);ctx.fill();let gr=ctx.createLinearGradient(o.x,o.y-o.h/2,o.x,o.y+o.h/2);gr.addColorStop(0,'#455367');gr.addColorStop(.22,'#273445');gr.addColorStop(1,'#182231');ctx.fillStyle=gr;roundRect(ctx,o.x-o.w/2,o.y-o.h/2,o.w,o.h,.12);ctx.fill();ctx.strokeStyle='#8291a340';ctx.lineWidth=.045;ctx.stroke();ctx.fillStyle='#a5b1c41a';ctx.fillRect(o.x-o.w/2+.12,o.y-o.h/2+.1,o.w-.24,.06);ctx.fillStyle='#53ded633';ctx.fillRect(o.x-o.w/2+.11,o.y+o.h/2-.14,o.w-.22,.035)}
ctx.strokeStyle='#a5b2c533';ctx.lineWidth=.08;roundRect(ctx,-11.7,-7.95,23.4,15.9,.55);ctx.stroke();ctx.restore()}
function drawHero(p,isPlayer){let c=isPlayer?'#63eee2':'#ff6384',dark=isPlayer?'#1c5b61':'#713145',x=p.x,y=p.y;ctx.save();ctx.translate(x,y);ctx.rotate(p.angle);ctx.globalAlpha=p.inv>0&&Math.floor(performance.now()/55)%2?.38:1;
// shadow and tapered energy trail
ctx.fillStyle='#03060b99';ctx.beginPath();ctx.ellipse(.1,.45,.8,.38,0,0,Math.PI*2);ctx.fill();if(p.dash>0){ctx.globalAlpha=.35;ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(-.75,0,.8,.27,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
// body in perspective layers
ctx.fillStyle='#080d17';ctx.beginPath();ctx.ellipse(0,.1,.61,.53,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.flash>0?'#ffffff':dark;ctx.beginPath();ctx.ellipse(0,-.04,.53,.49,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=c;ctx.lineWidth=.09;ctx.beginPath();ctx.ellipse(0,-.04,.54,.49,0,0,Math.PI*2);ctx.stroke();
// shoulder plates
ctx.fillStyle=isPlayer?'#a1fff1':'#ff9bb0';for(let s of [-1,1]){ctx.beginPath();ctx.ellipse(-.08,s*.37,.28,.19,s*.2,0,Math.PI*2);ctx.fill()}
// faceplate/head facing gun
ctx.fillStyle='#0c1521';ctx.beginPath();ctx.ellipse(.16,0,.31,.32,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c;ctx.shadowColor=c;ctx.shadowBlur=.3;ctx.beginPath();ctx.ellipse(.28,-.015,.13,.06,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
// weapon
ctx.fillStyle='#172230';roundRect(ctx,.32,-.13,.53,.26,.08);ctx.fill();ctx.fillStyle=c;ctx.fillRect(.75,-.065,.23,.13);ctx.fillStyle='#d9ffff';ctx.fillRect(.91,-.035,.13,.07);
// charge halo
if(p.over>0){ctx.strokeStyle='#fff0ad';ctx.lineWidth=.075;ctx.beginPath();ctx.arc(0,0,.76+Math.sin(performance.now()*.02)*.06,0,Math.PI*2);ctx.stroke()}
ctx.restore();ctx.globalAlpha=1;
// floating ring base
ctx.strokeStyle=c+'66';ctx.lineWidth=.06;ctx.beginPath();ctx.ellipse(x,y+.28,.62,.21,0,0,Math.PI*2);ctx.stroke();
// hp tick
ctx.fillStyle='#05080e';ctx.fillRect(x-.43,y-.98,.86,.09);ctx.fillStyle=c;ctx.fillRect(x-.43,y-.98,.86*clamp(p.hp/100,0,1),.09);
}
function draw(){ctx.setTransform(devicePixelRatio||1,0,0,devicePixelRatio||1,0,0);ctx.clearRect(0,0,W,H);drawArena();ctx.save();ctx.translate(W/2,cy);ctx.scale(S,S*.78);if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));
for(let r of rings){ctx.globalAlpha=clamp(r.life/.65,0,1)*.75;ctx.strokeStyle=r.color;ctx.lineWidth=.08;ctx.beginPath();ctx.arc(r.x,r.y,r.r,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=1;
for(let b of bullets){ctx.fillStyle=b.color;ctx.shadowColor=b.color;ctx.shadowBlur=.25;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.3;ctx.beginPath();ctx.ellipse(b.x-b.vx*.035,b.y-b.vy*.035,b.r*2.6,b.r*.6,Math.atan2(b.vy,b.vx),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.shadowBlur=0}
for(let p of particles){ctx.globalAlpha=clamp(p.life/.65,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
drawHero(player,true);drawHero(enemy,false);ctx.restore()}

