function collides(x,y,r){if(Math.abs(x)>bounds.x-r||Math.abs(y)>bounds.y-r)return true;for(const o of blocks){let qx=clamp(x,o.x-o.w/2,o.x+o.w/2),qy=clamp(y,o.y-o.h/2,o.y+o.h/2);if(Math.hypot(x-qx,y-qy)<r)return true}return false}
function move(p,dt){let nx=p.x+p.vx*dt,ny=p.y+p.vy*dt;if(!collides(nx,p.y,p.r))p.x=nx;else p.vx*=-.2;if(!collides(p.x,ny,p.r))p.y=ny;else p.vy*=-.2;p.x=clamp(p.x,-bounds.x+p.r,bounds.x-p.r);p.y=clamp(p.y,-bounds.y+p.r,bounds.y-p.r)}
function step(dt){if(!active)return;elapsed+=dt;roundTime=Math.max(0,90-elapsed);shake=Math.max(0,shake-dt);for(let p of [player,enemy]){p.fire=Math.max(0,p.fire-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.pulseCd=Math.max(0,p.pulseCd-dt);p.inv=Math.max(0,p.inv-dt);p.flash=Math.max(0,p.flash-dt);p.over=Math.max(0,p.over-dt)}
let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);
if(stickOn){dx=stickX;dy=stickY}let mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag}let speed=player.over>0?7.3:6.2;if(player.dash<=0){let blend=1-Math.exp(-dt*12);player.vx+=(dx*speed-player.vx)*blend;player.vy+=(dy*speed-player.vy)*blend}else player.dash=Math.max(0,player.dash-dt);move(player,dt);if(Math.hypot(dx,dy)>.1&&stickOn)player.angle=Math.atan2(enemy.y-player.y,enemy.x-player.x);else{let aim=toWorld(mouse.x,mouse.y);player.angle=Math.atan2(aim.y-player.y,aim.x-player.x)}
if(mouse.down&&player.fire<=0){shoot(player,enemy,'player');player.fire=player.over>0?.115:.23}
// Enemy warden keeps mid-range, strafes and actively answers fire
let ex=player.x-enemy.x,ey=player.y-enemy.y,dist=Math.hypot(ex,ey)||1;enemy.angle=Math.atan2(ey,ex);let toward=clamp((dist-5.3)/3,-.55,1),strafe=Math.sin(elapsed*1.35)*.48;let exd=ex/dist*toward-ey/dist*strafe,eyd=ey/dist*toward+ex/dist*strafe;let em=Math.hypot(exd,eyd)||1;let espeed=enemy.over>0?5.3:4.15;enemy.vx+=(exd/em*espeed-enemy.vx)*(1-Math.exp(-dt*5));enemy.vy+=(eyd/em*espeed-enemy.vy)*(1-Math.exp(-dt*5));if(enemy.dash<=0&&dist<3.2&&enemy.dashCd<=0){dash(enemy,-ex/dist,-ey/dist);enemy.dashCd=4.3}else if(enemy.dash>0)enemy.dash=Math.max(0,enemy.dash-dt);move(enemy,dt);
if(enemy.fire<=0&&dist<11.5){shoot(enemy,player,'enemy',dist<4?.06:.025);enemy.fire=enemy.over>0?.42:rand(.72,1.05)}if(enemy.pulseCd<=0&&dist<3.2)pulse(enemy,player);if(enemy.ult>=100&&dist<6)ultimate(enemy,player);
for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let target=b.team==='player'?enemy:player;if(b.life<=0||Math.abs(b.x)>12||Math.abs(b.y)>8||collides(b.x,b.y,b.r)){bullets.splice(i,1);continue}if(Math.hypot(b.x-target.x,b.y-target.y)<target.r+.13){hit(target,b);bullets.splice(i,1);if(target.hp<=0){updateHud();endGame(target===enemy);return}}}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}for(let i=rings.length-1;i>=0;i--){let r=rings[i];r.life-=dt;r.r+=(r.max-r.r)*dt*7;if(r.life<=0)rings.splice(i,1)}
if(roundTime<=0){endGame(player.hp>=enemy.hp);return}if(Math.random()<dt*4)updateHud()}
