function trigger(action){if(!active)return;if(action==='dash')dash(player,dx||Math.cos(player.angle),dy||Math.sin(player.angle));if(action==='pulse')pulse(player,enemy);if(action==='ult')ultimate(player,enemy);if(action==='fire'){mouse.down=true;player.angle=Math.atan2(enemy.y-player.y,enemy.x-player.x)}}
